import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def calculate_R(n):
    f_Kn = combinations(n, 3)  # Number of triangles
    g_Kn = combinations(n, 4)  # Number of tetrahedra

    if f_Kn == 0:
        return "Undefined"

    R_Kn = (g_Kn ** 3) / (f_Kn ** 4)
    return R_Kn

results = {}
for n in range(4, 9):
    r = calculate_R(n)
    results[n] = r

print(results)

